#include <stdio.h>

int main(void)
{
    int a = 7, b = 9;
    const int *p = &a;
    p = &b;
    b = 10;
    printf("%d\n", *p);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int score = 30;
    int *const p = &score;
    *p = 50;
    printf("%d\n", score);
    return 0;
}

#include <stdio.h>

int main(void)
{
    int score = 40;
    const int *const view = &score;
    score = 60;
    printf("%d\n", *view);
    return 0;
}

